    27→func randFieldElement() [32]byte {
    28→	bytes := make([]byte, 32)
    29→	_, err := rand.Read(bytes)
    30→	if err != nil {
    31→		panic("failed to get random field element")
    32→	}
    33→	var r fr.Element
    34→	r.SetBytes(bytes)
    35→
    36→	return gokzg4844.SerializeScalar(r)
    37→}
