   181→// Body is a simple (mutable, non-safe) data container for storing and moving
   182→// a block's data contents (transactions and uncles) together.
   183→type Body struct {
   184→	Transactions []*Transaction
   185→	Uncles       []*Header
   186→	Withdrawals  []*Withdrawal `rlp:"optional"`
   187→}
   188→
   189→// Block represents an Ethereum block.
   190→//
   191→// Note the Block type tries to be 'immutable', and contains certain caches that rely
   192→// on that. The rules around block immutability are as follows:
   193→//
   194→//   - We copy all data when the block is constructed. This makes references held inside
   195→//     the block independent of whatever value was passed in.
   196→//
   197→//   - We copy all header data on access. This is because any change to the header would mess
   198→//     up the cached hash and size values in the block. Calling code is expected to take
   199→//     advantage of this to avoid over-allocating!
   200→//
   201→//   - When new body data is attached to the block, a shallow copy of the block is returned.
   202→//     This ensures block modifications are race-free.
   203→//
   204→//   - We do not copy body data on access because it does not affect the caches, and also
   205→//     because it would be too expensive.
   206→type Block struct {
   207→	header       *Header
   208→	uncles       []*Header
   209→	transactions Transactions
   210→	withdrawals  Withdrawals
   211→
   212→	// witness is not an encoded part of the block body.
   213→	// It is held in Block in order for easy relaying to the places
   214→	// that process it.
   215→	witness *ExecutionWitness
   216→
   217→	// caches
   218→	hash atomic.Pointer[common.Hash]
   219→	size atomic.Uint64
   220→
   221→	// These fields are used by package eth to track
   222→	// inter-peer block relay.
   223→	ReceivedAt   time.Time
   224→	ReceivedFrom interface{}
   225→}
   226→
   227→// "external" block encoding. used for eth protocol, etc.
   228→type extblock struct {
   229→	Header      *Header
   230→	Txs         []*Transaction
   231→	Uncles      []*Header
   232→	Withdrawals []*Withdrawal `rlp:"optional"`
   233→}
   234→
   235→// NewBlock creates a new block. The input data is copied, changes to header and to the
   236→// field values will not affect the block.
   237→//
   238→// The body elements and the receipts are used to recompute and overwrite the
   239→// relevant portions of the header.
   240→//
   241→// The receipt's bloom must already calculated for the block's bloom to be
   242→// correctly calculated.
   243→func NewBlock(header *Header, body *Body, receipts []*Receipt, hasher TrieHasher) *Block {
   244→	if body == nil {
   245→		body = &Body{}
   246→	}
   247→	var (
   248→		b           = NewBlockWithHeader(header)
   249→		txs         = body.Transactions
   250→		uncles      = body.Uncles
   251→		withdrawals = body.Withdrawals
   252→	)
   253→
   254→	if len(txs) == 0 {
   255→		b.header.TxHash = EmptyTxsHash
   256→	} else {
   257→		b.header.TxHash = DeriveSha(Transactions(txs), hasher)
   258→		b.transactions = make(Transactions, len(txs))
   259→		copy(b.transactions, txs)
   260→	}
   261→
   262→	if len(receipts) == 0 {
   263→		b.header.ReceiptHash = EmptyReceiptsHash
   264→	} else {
   265→		b.header.ReceiptHash = DeriveSha(Receipts(receipts), hasher)
   266→		// Receipts must go through MakeReceipt to calculate the receipt's bloom
   267→		// already. Merge the receipt's bloom together instead of recalculating
   268→		// everything.
   269→		b.header.Bloom = MergeBloom(receipts)
   270→	}
   271→
   272→	if len(uncles) == 0 {
   273→		b.header.UncleHash = EmptyUncleHash
   274→	} else {
   275→		b.header.UncleHash = CalcUncleHash(uncles)
   276→		b.uncles = make([]*Header, len(uncles))
   277→		for i := range uncles {
   278→			b.uncles[i] = CopyHeader(uncles[i])
   279→		}
   280→	}
   281→
   282→	if withdrawals == nil {
   283→		b.header.WithdrawalsHash = nil
   284→	} else if len(withdrawals) == 0 {
   285→		b.header.WithdrawalsHash = &EmptyWithdrawalsHash
   286→		b.withdrawals = Withdrawals{}
   287→	} else {
   288→		hash := DeriveSha(Withdrawals(withdrawals), hasher)
   289→		b.header.WithdrawalsHash = &hash
