   105→// NewReceipt creates a barebone transaction receipt, copying the init fields.
   106→// Deprecated: create receipts using a struct literal instead.
   107→func NewReceipt(root []byte, failed bool, cumulativeGasUsed uint64) *Receipt {
   108→	r := &Receipt{
   109→		Type:              LegacyTxType,
   110→		PostState:         common.CopyBytes(root),
   111→		CumulativeGasUsed: cumulativeGasUsed,
   112→	}
   113→	if failed {
   114→		r.Status = ReceiptStatusFailed
   115→	} else {
   116→		r.Status = ReceiptStatusSuccessful
   117→	}
   118→	return r
   119→}
