   121→// EncodeRLP implements rlp.Encoder, and flattens the consensus fields of a receipt
   122→// into an RLP stream. If no post state is present, byzantium fork is assumed.
   123→func (r *Receipt) EncodeRLP(w io.Writer) error {
   124→	data := &receiptRLP{r.statusEncoding(), r.CumulativeGasUsed, r.Bloom, r.Logs}
   125→	if r.Type == LegacyTxType {
   126→		return rlp.Encode(w, data)
   127→	}
   128→	buf := encodeBufferPool.Get().(*bytes.Buffer)
   129→	defer encodeBufferPool.Put(buf)
   130→	buf.Reset()
   131→	if err := r.encodeTyped(data, buf); err != nil {
   132→		return err
   133→	}
   134→	return rlp.Encode(w, buf.Bytes())
   135→}
   136→
   137→// encodeTyped writes the canonical encoding of a typed receipt to w.
   138→func (r *Receipt) encodeTyped(data *receiptRLP, w *bytes.Buffer) error {
   139→	w.WriteByte(r.Type)
   140→	return rlp.Encode(w, data)
   141→}
