   317→// ReceiptForStorage is a wrapper around a Receipt with RLP serialization
   318→// that omits the Bloom field. The Bloom field is recomputed by DeriveFields.
   319→type ReceiptForStorage Receipt
   320→
   321→// EncodeRLP implements rlp.Encoder, and flattens all content fields of a receipt
   322→// into an RLP stream.
   323→func (r *ReceiptForStorage) EncodeRLP(_w io.Writer) error {
   324→	w := rlp.NewEncoderBuffer(_w)
   325→	outerList := w.List()
   326→	w.WriteBytes((*Receipt)(r).statusEncoding())
   327→	w.WriteUint64(r.CumulativeGasUsed)
   328→	logList := w.List()
   329→	for _, log := range r.Logs {
   330→		if err := log.EncodeRLP(w); err != nil {
   331→			return err
   332→		}
   333→	}
   334→	w.ListEnd(logList)
   335→	w.ListEnd(outerList)
   336→	return w.Flush()
   337→}
   338→
   339→// DecodeRLP implements rlp.Decoder, and loads both consensus and implementation
   340→// fields of a receipt from an RLP stream.
   341→func (r *ReceiptForStorage) DecodeRLP(s *rlp.Stream) error {
   342→	var stored storedReceiptRLP
   343→	if err := s.Decode(&stored); err != nil {
   344→		return err
   345→	}
   346→	if err := (*Receipt)(r).setStatus(stored.PostStateOrStatus); err != nil {
   347→		return err
   348→	}
   349→	r.CumulativeGasUsed = stored.CumulativeGasUsed
   350→	r.Logs = stored.Logs
   351→
   352→	return nil
   353→}
