   237→	return nil
   238→}
   239→
   240→func (r *Receipt) statusEncoding() []byte {
   241→	if len(r.PostState) == 0 {
   242→		if r.Status == ReceiptStatusFailed {
   243→			return receiptStatusFailedRLP
   244→		}
   245→		return receiptStatusSuccessfulRLP
   246→	}
   247→	return r.PostState
   248→}
