   250→// Size returns the approximate memory used by all internal contents. It is used
   251→// to approximate and limit the memory consumption of various caches.
   252→func (r *Receipt) Size() common.StorageSize {
   253→	size := common.StorageSize(unsafe.Sizeof(*r)) + common.StorageSize(len(r.PostState))
   254→	size += common.StorageSize(len(r.Logs)) * common.StorageSize(unsafe.Sizeof(Log{}))
   255→	for _, log := range r.Logs {
   256→		size += common.StorageSize(len(log.Topics)*common.HashLength + len(log.Data))
   257→	}
   258→	return size
   259→}
