   261→// DeriveReceiptContext holds the contextual information needed to derive a receipt
   262→type DeriveReceiptContext struct {
   263→	BlockHash    common.Hash
   264→	BlockNumber  uint64
   265→	BlockTime    uint64
   266→	BaseFee      *big.Int
   267→	BlobGasPrice *big.Int
   268→	GasUsed      uint64
   269→	LogIndex     uint // Number of logs in the block until this receipt
   270→	Tx           *Transaction
   271→	TxIndex      uint
   272→}
   273→
   274→// DeriveFields fills the receipt with computed fields based on consensus
   275→// data and contextual infos like containing block and transactions.
   276→func (r *Receipt) DeriveFields(signer Signer, context DeriveReceiptContext) {
   277→	// The transaction type and hash can be retrieved from the transaction itself
   278→	r.Type = context.Tx.Type()
   279→	r.TxHash = context.Tx.Hash()
   280→	r.GasUsed = context.GasUsed
   281→	r.EffectiveGasPrice = context.Tx.inner.effectiveGasPrice(new(big.Int), context.BaseFee)
   282→
   283→	// EIP-4844 blob transaction fields
   284→	if context.Tx.Type() == BlobTxType {
   285→		r.BlobGasUsed = context.Tx.BlobGas()
   286→		r.BlobGasPrice = context.BlobGasPrice
   287→	}
   288→
   289→	// Block location fields
   290→	r.BlockHash = context.BlockHash
   291→	r.BlockNumber = new(big.Int).SetUint64(context.BlockNumber)
   292→	r.TransactionIndex = context.TxIndex
   293→
   294→	// The contract address can be derived from the transaction itself
   295→	if context.Tx.To() == nil {
   296→		// Deriving the signer is expensive, only do if it's actually needed
   297→		from, _ := Sender(signer, context.Tx)
   298→		r.ContractAddress = crypto.CreateAddress(from, context.Tx.Nonce())
   299→	} else {
   300→		r.ContractAddress = common.Address{}
   301→	}
   302→	// The derived log fields can simply be set from the block and transaction
   303→	logIndex := context.LogIndex
   304→	for j := 0; j < len(r.Logs); j++ {
   305→		r.Logs[j].BlockNumber = context.BlockNumber
   306→		r.Logs[j].BlockHash = context.BlockHash
   307→		r.Logs[j].BlockTimestamp = context.BlockTime
   308→		r.Logs[j].TxHash = r.TxHash
   309→		r.Logs[j].TxIndex = context.TxIndex
   310→		r.Logs[j].Index = logIndex
   311→		logIndex++
   312→	}
   313→	// Also derive the Bloom if not derived yet
   314→	r.Bloom = CreateBloom(r)
   315→}
