   109→		Type:              LegacyTxType,
   110→		PostState:         common.CopyBytes(root),
   111→		CumulativeGasUsed: cumulativeGasUsed,
   112→	}
   113→	if failed {
   114→		r.Status = ReceiptStatusFailed
   115→	} else {
   116→		r.Status = ReceiptStatusSuccessful
   117→	}
   118→	return r
   119→}
