   143→// MarshalBinary returns the consensus encoding of the receipt.
   144→func (r *Receipt) MarshalBinary() ([]byte, error) {
   145→	if r.Type == LegacyTxType {
   146→		return rlp.EncodeToBytes(r)
   147→	}
   148→	data := &receiptRLP{r.statusEncoding(), r.CumulativeGasUsed, r.Bloom, r.Logs}
   149→	var buf bytes.Buffer
   150→	err := r.encodeTyped(data, &buf)
   151→	return buf.Bytes(), err
   152→}
   153→
   154→// DecodeRLP implements rlp.Decoder, and loads the consensus fields of a receipt
   155→// from an RLP stream.
   156→func (r *Receipt) DecodeRLP(s *rlp.Stream) error {
   157→	kind, size, err := s.Kind()
   158→	switch {
   159→	case err != nil:
   160→		return err
   161→	case kind == rlp.List:
   162→		// It's a legacy receipt.
   163→		var dec receiptRLP
   164→		if err := s.Decode(&dec); err != nil {
   165→			return err
   166→		}
   167→		r.Type = LegacyTxType
   168→		return r.setFromRLP(dec)
   169→	case kind == rlp.Byte:
   170→		return errShortTypedReceipt
   171→	default:
   172→		// It's an EIP-2718 typed tx receipt.
   173→		b, buf, err := getPooledBuffer(size)
   174→		if err != nil {
   175→			return err
   176→		}
   177→		defer encodeBufferPool.Put(buf)
   178→		if err := s.ReadBytes(b); err != nil {
   179→			return err
   180→		}
   181→		return r.decodeTyped(b)
   182→	}
   183→}
