   185→// UnmarshalBinary decodes the consensus encoding of receipts.
   186→// It supports legacy RLP receipts and EIP-2718 typed receipts.
   187→func (r *Receipt) UnmarshalBinary(b []byte) error {
   188→	if len(b) > 0 && b[0] > 0x7f {
   189→		// It's a legacy receipt decode the RLP
   190→		var data receiptRLP
   191→		err := rlp.DecodeBytes(b, &data)
   192→		if err != nil {
   193→			return err
   194→		}
   195→		r.Type = LegacyTxType
   196→		return r.setFromRLP(data)
   197→	}
   198→	// It's an EIP2718 typed transaction envelope.
   199→	return r.decodeTyped(b)
   200→}
   201→
   202→// decodeTyped decodes a typed receipt from the canonical format.
   203→func (r *Receipt) decodeTyped(b []byte) error {
   204→	if len(b) <= 1 {
   205→		return errShortTypedReceipt
   206→	}
   207→	switch b[0] {
   208→	case DynamicFeeTxType, AccessListTxType, BlobTxType, SetCodeTxType:
   209→		var data receiptRLP
   210→		err := rlp.DecodeBytes(b[1:], &data)
   211→		if err != nil {
   212→			return err
   213→		}
   214→		r.Type = b[0]
   215→		return r.setFromRLP(data)
   216→	default:
   217→		return ErrTxTypeNotSupported
   218→	}
   219→}
   220→
   221→func (r *Receipt) setFromRLP(data receiptRLP) error {
   222→	r.CumulativeGasUsed, r.Bloom, r.Logs = data.CumulativeGasUsed, data.Bloom, data.Logs
   223→	return r.setStatus(data.PostStateOrStatus)
   224→}
   225→
   226→func (r *Receipt) setStatus(postStateOrStatus []byte) error {
   227→	switch {
   228→	case bytes.Equal(postStateOrStatus, receiptStatusSuccessfulRLP):
   229→		r.Status = ReceiptStatusSuccessful
   230→	case bytes.Equal(postStateOrStatus, receiptStatusFailedRLP):
   231→		r.Status = ReceiptStatusFailed
   232→	case len(postStateOrStatus) == len(common.Hash{}):
   233→		r.PostState = postStateOrStatus
   234→	default:
   235→		return fmt.Errorf("invalid receipt status %x", postStateOrStatus)
   236→	}
   237→	return nil
   238→}
   239→
   240→func (r *Receipt) statusEncoding() []byte {
   241→	if len(r.PostState) == 0 {
   242→		if r.Status == ReceiptStatusFailed {
   243→			return receiptStatusFailedRLP
   244→		}
   245→		return receiptStatusSuccessfulRLP
   246→	}
   247→	return r.PostState
   248→}
