   355→// Receipts implements DerivableList for receipts.
   356→type Receipts []*Receipt
   357→
   358→// Len returns the number of receipts in this list.
   359→func (rs Receipts) Len() int { return len(rs) }
   360→
   361→// EncodeIndex encodes the i'th receipt to w.
   362→func (rs Receipts) EncodeIndex(i int, w *bytes.Buffer) {
   363→	r := rs[i]
   364→	data := &receiptRLP{r.statusEncoding(), r.CumulativeGasUsed, r.Bloom, r.Logs}
   365→	if r.Type == LegacyTxType {
   366→		rlp.Encode(w, data)
   367→		return
   368→	}
   369→	w.WriteByte(r.Type)
   370→	switch r.Type {
   371→	case AccessListTxType, DynamicFeeTxType, BlobTxType, SetCodeTxType:
   372→		rlp.Encode(w, data)
   373→	default:
   374→		// For unsupported types, write nothing. Since this is for
   375→		// DeriveSha, the error will be caught matching the derived hash
   376→		// to the block.
   377→	}
   378→}
   379→
   380→// DeriveFields fills the receipts with their computed fields based on consensus
   381→// data and contextual infos like containing block and transactions.
   382→func (rs Receipts) DeriveFields(config *params.ChainConfig, blockHash common.Hash, blockNumber uint64, blockTime uint64, baseFee *big.Int, blobGasPrice *big.Int, txs []*Transaction) error {
   383→	signer := MakeSigner(config, new(big.Int).SetUint64(blockNumber), blockTime)
   384→
   385→	logIndex := uint(0)
   386→	if len(txs) != len(rs) {
   387→		return errors.New("transaction and receipt count mismatch")
   388→	}
   389→	for i := 0; i < len(rs); i++ {
   390→		var cumulativeGasUsed uint64
   391→		if i > 0 {
   392→			cumulativeGasUsed = rs[i-1].CumulativeGasUsed
   393→		}
   394→		rs[i].DeriveFields(signer, DeriveReceiptContext{
   395→			BlockHash:    blockHash,
   396→			BlockNumber:  blockNumber,
   397→			BlockTime:    blockTime,
   398→			BaseFee:      baseFee,
   399→			BlobGasPrice: blobGasPrice,
   400→			GasUsed:      rs[i].CumulativeGasUsed - cumulativeGasUsed,
   401→			LogIndex:     logIndex,
   402→			Tx:           txs[i],
   403→			TxIndex:      uint(i),
   404→		})
   405→		logIndex += uint(len(rs[i].Logs))
   406→	}
   407→	return nil
   408→}
   409→
   410→// EncodeBlockReceiptLists encodes a list of block receipt lists into RLP.
   411→func EncodeBlockReceiptLists(receipts []Receipts) []rlp.RawValue {
   412→	var storageReceipts []*ReceiptForStorage
   413→	result := make([]rlp.RawValue, len(receipts))
   414→	for i, receipt := range receipts {
   415→		storageReceipts = storageReceipts[:0]
   416→		for _, r := range receipt {
   417→			storageReceipts = append(storageReceipts, (*ReceiptForStorage)(r))
   418→		}
   419→		bytes, err := rlp.EncodeToBytes(storageReceipts)
   420→		if err != nil {
   421→			log.Crit("Failed to encode block receipts", "err", err)
   422→		}
   423→		result[i] = bytes
   424→	}
   425→	return result
   426→}
